def fwd(tokens, mods=None):
    # tokens [B,3]; mods dict site->function(x_activation)->new
    B=len(tokens)
    x = W['W_E'][tokens] + W['W_pos'][None]   # B,3,128
    for pos in range(3):
        a = x[:,pos]
        if mods and ('embed.%d'%pos) in mods: a=mods['embed.%d'%pos](a)
        x[:,pos]=a
    q = x[:,-1]@W['W_Q']        # B,4,32
    k = x@W['W_K']              # B,3,4,32
    v = x@W['W_V']
    sc = np.einsum('bhd,bthd->bht',q,k)/np.sqrt(32)
    sc = sc - 1e9*np.triu(np.ones((3,3)),1)[None]  # causal: positions>last none; last attends all
    p = np.exp(sc-sc.max(-1,keepdims=True)); p/=p.sum(-1,keepdims=True)
    if mods and 'attn_pattern' in mods: p=mods['attn_pattern'](p)
    o = np.einsum('bht,bthd->bhd',p,v) @ W['W_O']  # sum heads
    ao=o.sum(1)
    if mods and 'attn_out' in mods: ao=mods['attn_out'](ao)
    xm = x[:,-1]+ao
    if mods and 'resid_mid' in mods: xm=mods['resid_mid'](xm)
    pre = xm@W['W_in']
    if mods and 'mlp_pre' in mods: pre=mods['mlp_pre'](pre)
    post=np.maximum(pre,0)
    if mods and 'mlp_post' in mods: post=mods['mlp_post'](post)
    mo = post@W['W_out']
    if mods and 'mlp_out' in mods: mo=mods['mlp_out'](mo)
    xp = xm+mo
    if mods and 'resid_post' in mods: xp=mods['resid_post'](xp)
    return xp@W['W_U'], {'p':p,'attn_out':ao,'xm':xm,'pre':pre,'post':post,'mo':mo,'xp':xp}
